INSERT INTO "reviews" ("id", "app_id", "user_id", "author_name", "author_role", "stars", "text", "status", "created_at") VALUES ('rev-001', 'APP-4964', 'usr-admin-001', 'Trần Minh Hoàng', 'Kỹ Sư Quản Trị Hệ Thống IT', 5, 'Bộ công cụ DMH Tools Enterprise và Virtual CloudPool Storage phân tán Google Drive hoạt động cực kỳ ổn định. Tốc độ upload chunk mã hóa AES-256-GCM nhanh và tiết kiệm băng thông vượt bậc so với các giải pháp thông thường.', 'approved', '2026-10-01 10:15:00') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "app_id", "user_id", "author_name", "author_role", "stars", "text", "status", "created_at") VALUES ('rev-002', 'APP-4964', 'usr-admin-001', 'BS. Lê Quang Tuấn', 'Trưởng Phòng Khám Đa Khoa Sài Gòn', 5, 'Tính năng gọi bệnh nhân tự động TTS bằng AI và cầu nối máy nội soi 4K chạy mượt mà, giúp phòng khám giảm 70% thời gian chờ đợi của bệnh nhân và quản lý dữ liệu chẩn đoán hình ảnh rất an tâm.', 'approved', '2026-10-01 14:30:00') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "app_id", "user_id", "author_name", "author_role", "stars", "text", "status", "created_at") VALUES ('rev-003', 'APP-5192', 'usr-admin-001', 'Phạm Đức Thắng', 'Trưởng Nhóm DevOps & Cloud Architect', 5, 'Kiến trúc Go Monolith kết hợp Rust Core FFI và TiDB Cloud Serverless cực kỳ tối ưu, zero memory leak và thời gian đáp ứng API dưới 5ms. Rất khuyên dùng cho các doanh nghiệp cần hạ tầng bảo mật cao.', 'approved', '2026-10-02 09:45:00') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "app_id", "user_id", "author_name", "author_role", "stars", "text", "status", "created_at") VALUES ('rev-004', 'APP-7290', 'usr-admin-001', 'Nguyễn Thị Mai Anh', 'Kỹ Thuật Viên Âm Thanh & Đa Phương Tiện', 5, 'Giao diện Cyber Nebula 3D đẹp mắt, trực quan và dễ sử dụng. Bộ xử lý âm thanh AI Equalizer 10 băng tần cho chất âm chi tiết, khử nhiễu micro theo thời gian thực rất ấn tượng.', 'approved', '2026-10-02 16:20:00') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "app_id", "user_id", "author_name", "author_role", "stars", "text", "status", "created_at") VALUES ('rev-005', 'APP-4964', 'usr-admin-001', 'Vũ Đình Khoa', 'Chuyên Viên Cứu Hộ & Sửa Chữa Máy Tính', 5, '41 công cụ sửa lỗi Windows sâu của DMH Tools xử lý dứt điểm các ca lỗi Print Spooler, chia sẻ máy in LAN 0x11b và trích xuất driver chỉ trong 1 click, không cần cài lại Windows.', 'approved', '2026-10-03 08:30:00') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "app_id", "user_id", "author_name", "author_role", "stars", "text", "status", "created_at") VALUES ('rev-006', 'APP-3820', 'usr-admin-001', 'Đỗ Gia Huy', 'Kỹ Sư Phần Mềm Fullstack', 5, 'Hệ thống WebDAV và API phân phối Anycast CDN cho ứng dụng cực kỳ tiện lợi. Đội ngũ SupportFlast hỗ trợ kỹ thuật rất tận tình và chuyên nghiệp qua Zalo.', 'approved', '2026-10-03 11:00:00') ON CONFLICT DO NOTHING;
