INSERT INTO "system_releases" ("version", "title", "date", "build_hash", "notes", "published_by") VALUES ('v1.1.3', 'DMH Tools v1.1.3: Sửa Lỗi compare_server ENOENT và Tách Cột CCT Biểu 01 BHYT', '2026-10-07', '2b32488', '{"id":"rel-dmh-1.1.3","type":"fix","changes":["[fix] Khắc phục triệt để lỗi spawn compare_server.exe ENOENT khiến máy chủ Python bị sập ngầm","[feat] Phân tách chuẩn xác 2 cột Bệnh nhân cùng chi trả (CCT - T_BNCCT) và Bệnh nhân tự trả (TT - T_BNTT) theo Biểu 01 BHYT","[feat] Tự động khớp 100% các cột chuẩn Biểu 01 giữa Cổng Giám Định BHYT và HIS Nội bộ bệnh viện","[perf] Tối ưu hóa hiệu năng đối chiếu song song và đóng gói sẵn tệp thực thi trong bản cài đặt 153MB"],"active":true,"created_at":"2026-10-07T17:16:57+07:00"}', 'Dương Mạnh Hùng (DMH Tech)') ON CONFLICT DO NOTHING;
INSERT INTO "system_releases" ("version", "title", "date", "build_hash", "notes", "published_by") VALUES ('v1.1.4', 'DMH Tools v1.1.4: Nâng Cấp Toàn Diện & Tối Ưu Hóa Giao Diện', '2026-10-08', '2b32488', '{"id":"rel-20261008-165039","type":"fix","changes":["[feat] Phát hành chính thức bản cập nhật v1.1.4 tối ưu hóa hiệu năng","[fix] Khắc phục triệt để lỗi bố cục hiển thị khu vực Triển Khai \u0026 Cài Đặt (PcToolsTab)","[feat] Hoàn thiện giao diện đối chiếu BHYT chuyên sâu và tải OTA ngầm 1-chạm"],"active":true,"created_at":"2026-10-08T16:50:39+07:00"}', 'Dương Mạnh Hùng (DMH Tech)') ON CONFLICT DO NOTHING;
INSERT INTO "system_releases" ("version", "title", "date", "build_hash", "notes", "published_by") VALUES ('v1.1.5', 'DMH Tools v1.1.5: Tự Động Giải Mã BHYT & Nâng Cấp Toàn Diện', '2026-10-08', '2b32488', '{"id":"rel-20261008-171129","type":"feat","changes":["[feat] Phát hành chính thức phiên bản v1.1.5","[feat] Tự động giải mã chuẩn BHYT: Giới tính (1-\u003eNam, 2-\u003eNữ), Ngày sinh QĐ 130 loại bỏ 00:00, Ngày vào/ra 12 số","[fix] Khắc phục triệt để hiển thị ngày vào/ra trong bảng đối chiếu song song modal (không còn hiện — vs —)","[feat] Tự động kiểm tra và thông báo cập nhật phiên bản mới ngay khi khởi động"],"active":true,"created_at":"2026-10-08T17:11:29+07:00"}', 'Dương Mạnh Hùng (DMH Tech)') ON CONFLICT DO NOTHING;
INSERT INTO "system_releases" ("version", "title", "date", "build_hash", "notes", "published_by") VALUES ('v1.1.6', 'DMH Tools v1.1.6: Nâng Cấp Bộ Cài Đặt Trực Quan & Tối Ưu Hệ Thống', '2026-10-09', '2b32488', '{"id":"rel-20261009-090200","type":"feat","changes":["[feat] Phát hành chính thức phiên bản v1.1.6","[fix] Khắc phục triệt để lỗi khi bấm Cập nhật thì app bị thoát mà không hiển thị bộ cài đặt","[feat] Bộ cài đặt NSIS chạy trực quan với thanh tiến trình cài đặt và tự động mở lại app sau khi hoàn tất","[feat] Bổ sung nút \"Mở Thư Mục\" cứu hộ trên hộp thoại thông báo cập nhật","[feat] Tự động giải mã chuẩn BHYT, hiển thị chuẩn xác ngày vào/ra trên bảng đối chiếu"],"active":true,"created_at":"2026-10-09T09:02:00+07:00"}', 'Dương Mạnh Hùng (DMH Tech)') ON CONFLICT DO NOTHING;
